import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import {
  Autocomplete as AriaAutocomplete,
  type AutocompleteProps,
  useFilter,
} from "react-aria-components";

export function Autocomplete({ filter, ...props }: AutocompleteProps) {
  const { contains } = useFilter({ sensitivity: "base" });
  return <AriaAutocomplete filter={filter ?? contains} {...props} />;
}

import { Children, type ReactNode } from "react";
import { tv, type VariantProps } from "tailwind-variants";

export function buttonLabel(children: ReactNode): ReactNode {
  const parts: ReactNode[] = [];
  let text = "";
  const flush = () => {
    if (text.trim()) {
      parts.push(
        <span
          key={`label-${parts.length}`}
          data-slot="button-label"
          className="min-w-0 truncate"
        >
          {text}
        </span>,
      );
    }
    text = "";
  };
  for (const child of Children.toArray(children)) {
    if (typeof child === "string" || typeof child === "number") {
      text += child;
    } else {
      flush();
      parts.push(child);
    }
  }
  flush();
  return parts;
}

export const touchTarget =
  "relative pointer-coarse:after:absolute pointer-coarse:after:inset-x-0 pointer-coarse:after:top-1/2 pointer-coarse:after:h-[max(100%,var(--touch-target,2.75rem))] pointer-coarse:after:-translate-y-1/2";

export const buttonStyles = tv({
  base: "inline-flex min-w-0 max-w-full shrink-0 cursor-default items-center justify-center whitespace-nowrap rounded-md font-medium tracking-[-0.01em] outline-offset-4 outline-transparent transition-[color,background-color,border-color,box-shadow,scale,outline-color,outline-offset] duration-150 ease-out-quint disabled:cursor-default disabled:opacity-50 disabled:shadow-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring motion-reduce:outline-offset-2 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 pressed:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 pressed:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted",
      ghost:
        "text-foreground hover:bg-muted in-data-[item-highlight=under]:hover:bg-transparent pressed:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      minimal:
        "text-muted-foreground hover:bg-muted in-data-[item-highlight=under]:hover:bg-transparent hover:text-foreground pressed:bg-muted pressed:text-foreground",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 pressed:bg-destructive/90",
    },
    size: {
      xs: `h-7 gap-1.5 rounded-sm px-2.5 text-xs [&_svg:not([class*='size-'])]:size-3.5 ${touchTarget}`,
      sm: `h-9 gap-2 px-3.5 text-sm [&_svg:not([class*='size-'])]:size-4 ${touchTarget}`,
      md: "h-11 gap-2 px-5 text-sm [&_svg:not([class*='size-'])]:size-4",
      lg: "h-12 gap-2 px-6 text-sm [&_svg:not([class*='size-'])]:size-4",
      xl: "h-14 gap-2.5 rounded-lg px-7 text-base [&_svg:not([class*='size-'])]:size-5",
    },
    iconOnly: {
      true: "cursor-pointer px-0",
    },
  },
  compoundVariants: [
    { size: "xs", iconOnly: true, class: "w-7" },
    { size: "sm", iconOnly: true, class: "w-9" },
    {
      size: "md",
      iconOnly: true,
      class: "w-11 [&_svg:not([class*='size-'])]:size-4.5",
    },
    {
      size: "lg",
      iconOnly: true,
      class: "w-12 [&_svg:not([class*='size-'])]:size-5",
    },
    {
      size: "xl",
      iconOnly: true,
      class: "w-14 [&_svg:not([class*='size-'])]:size-6",
    },
  ],
  defaultVariants: { variant: "default", size: "md" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;

"use client";

import { createContext, type ReactNode, useContext } from "react";

export type Size = "xs" | "sm" | "md" | "lg" | "xl";

const SizeContext = createContext<Size | undefined>(undefined);

export function useSize(size?: Size) {
  const inherited = useContext(SizeContext);
  return size ?? inherited;
}

export function SizeProvider({
  size,
  children,
}: {
  size: Size | undefined;
  children: ReactNode;
}) {
  return <SizeContext value={size}>{children}</SizeContext>;
}

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import { springLayout } from "./motion";
import { type ButtonVariant, buttonLabel, buttonStyles } from "./button-styles";
import { type Size, useSize } from "./size";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: Size;
  iconOnly?: boolean;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

const pressStyles = "motion-safe:pressed:not-aria-expanded:scale-[0.96]";

export function Button({
  className,
  children,
  variant = "default",
  size: sizeProp,
  iconOnly = false,
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  const size = useSize(sizeProp) ?? "md";
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      layout={reduceMotion ? false : layout}
      transition={springLayout}
      className={composeRenderProps(className, (className) =>
        buttonStyles({
          variant,
          size,
          iconOnly,
          className: [!isStatic && pressStyles, className],
        }),
      )}
      {...props}
    >
      {composeRenderProps(children, buttonLabel)}
    </MotionButton>
  );
}

"use client";

import { XIcon } from "@phosphor-icons/react";
import { createContext, type ReactNode, useContext } from "react";
import {
  Dialog as AriaDialog,
  type DialogProps as AriaDialogProps,
  DialogTrigger as AriaDialogTrigger,
  composeRenderProps,
  type DialogTriggerProps,
  Heading,
  type HeadingProps,
  Modal,
  ModalOverlay,
  type ModalOverlayProps,
  Text,
  type TextProps,
} from "react-aria-components";
import { cn } from "./utils";
import { Button, type ButtonProps } from "./button";
import { SizeProvider } from "./size";

const CloseContext = createContext<(() => void) | null>(null);

export function Dialog(props: DialogTriggerProps) {
  return <AriaDialogTrigger {...props} />;
}

export function DialogTrigger({ className, ...props }: ButtonProps) {
  return <Button {...props} data-slot="dialog-trigger" className={className} />;
}

export interface DialogContentProps extends Omit<AriaDialogProps, "children"> {
  ref?: React.Ref<HTMLElement>;
  children: ReactNode;
  overlayProps?: Omit<ModalOverlayProps, "children" | "render">;
  modalProps?: Omit<React.ComponentProps<typeof Modal>, "children" | "render">;
  modalSlot?: string;
}

export function DialogContent({
  children,
  className,
  overlayProps,
  modalProps,
  modalSlot = "dialog-modal",
  ...props
}: DialogContentProps) {
  return (
    <ModalOverlay
      {...overlayProps}
      isDismissable={
        props.role === "alertdialog"
          ? false
          : (overlayProps?.isDismissable ?? true)
      }
      data-slot="dialog-overlay"
      className={composeRenderProps(overlayProps?.className, (className) =>
        cn(
          "fixed inset-x-0 top-0 z-50 grid h-[var(--visual-viewport-height,100dvh)] items-end overflow-clip bg-foreground/40 backdrop-blur-sm transition-[background-color,backdrop-filter] duration-240 ease-out-quint dark:bg-foreground/20 sm:place-items-center sm:p-4",
          "entering:bg-transparent entering:backdrop-blur-none exiting:bg-transparent exiting:backdrop-blur-none exiting:duration-160",
          className,
        ),
      )}
    >
      <Modal
        {...modalProps}
        data-slot={modalSlot}
        className={composeRenderProps(modalProps?.className, (className) =>
          cn(
            "relative max-h-[calc(var(--visual-viewport-height,100dvh)-1rem)] w-full min-w-0 max-w-full overflow-y-auto overscroll-contain rounded-t-2xl bg-card p-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] text-card-foreground [overflow-wrap:anywhere] shadow-[var(--shadow-float)] outline-none ring-1 ring-border/70 forced-colors:border sm:max-h-[calc(var(--visual-viewport-height,100dvh)-2rem)] sm:max-w-md sm:rounded-xl sm:p-6",
            "transition-[opacity,translate,scale] duration-260 ease-out-quint max-sm:duration-320 max-sm:ease-[cubic-bezier(0.32,0.72,0,1)]",
            "entering:opacity-0 motion-safe:max-sm:entering:translate-y-full motion-safe:sm:entering:translate-y-3 motion-safe:sm:entering:scale-96",
            "exiting:opacity-0 exiting:duration-180 max-sm:exiting:duration-240 motion-safe:max-sm:exiting:translate-y-full motion-safe:sm:exiting:translate-y-1.5 motion-safe:sm:exiting:scale-[0.985]",
            className,
          ),
        )}
      >
        <AriaDialog
          {...props}
          data-slot="dialog-content"
          className={cn("outline-none", className)}
        >
          {({ close }) => (
            <CloseContext.Provider value={close}>
              <SizeProvider size={undefined}>{children}</SizeProvider>
            </CloseContext.Provider>
          )}
        </AriaDialog>
      </Modal>
    </ModalOverlay>
  );
}

export function DialogHeader({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="dialog-header"
      className={cn(
        "flex items-start justify-between gap-4 *:data-[slot=dialog-close]:-my-2 *:data-[slot=dialog-close]:-me-3",
        className,
      )}
    />
  );
}

export function DialogTitle({ className, ...props }: HeadingProps) {
  return (
    <Heading
      {...props}
      slot="title"
      data-slot="dialog-title"
      className={cn(
        "min-w-0 text-xl font-semibold tracking-[-0.04em] [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function DialogDescription({ className, ...props }: TextProps) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="dialog-description"
      className={cn(
        "mt-2 block text-sm leading-6 text-muted-foreground [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function DialogFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="dialog-footer"
      className={cn("mt-5 flex flex-wrap justify-end gap-2", className)}
    />
  );
}

export function DialogClose({
  className,
  children,
  onPress,
  ...props
}: ButtonProps) {
  const close = useContext(CloseContext);
  return (
    <Button
      {...props}
      data-slot="dialog-close"
      variant={props.variant ?? "ghost"}
      iconOnly={props.iconOnly ?? !children}
      aria-label={
        props["aria-label"] ?? (children ? undefined : "Close dialog")
      }
      onPress={(event) => {
        onPress?.(event);
        close?.();
      }}
      className={className}
    >
      {children ?? <XIcon aria-hidden="true" />}
    </Button>
  );
}

import type { ComponentProps } from "react";
import { cn } from "./utils";

export function Kbd({ className, ...props }: ComponentProps<"kbd">) {
  return (
    <kbd
      data-slot="kbd"
      className={cn(
        "inline-flex min-h-5 min-w-5 shrink-0 items-center justify-center gap-1 rounded-sm border border-border bg-muted px-1.5 font-mono text-xs font-medium whitespace-nowrap text-foreground shadow-xs [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3",
        className,
      )}
      {...props}
    />
  );
}

export function KbdGroup({ className, ...props }: ComponentProps<"kbd">) {
  return (
    <kbd
      data-slot="kbd-group"
      className={cn(
        "inline-flex max-w-full shrink-0 flex-wrap items-center gap-1 font-sans whitespace-nowrap",
        className,
      )}
      {...props}
    />
  );
}

export function InlineCode({ className, ...props }: ComponentProps<"code">) {
  return (
    <code
      data-slot="inline-code"
      className={cn(
        "rounded-sm bg-muted px-1.5 py-0.5 font-mono text-[0.85em] text-foreground [overflow-wrap:anywhere] box-decoration-clone",
        className,
      )}
      {...props}
    />
  );
}

"use client";

import {
  animate,
  createGeneratorEasing,
  generateLinearEasing,
  spring,
  type Transition,
  useReducedMotion,
} from "motion/react";
import { type ReactElement, useLayoutEffect, useRef } from "react";
import { duration, easeOut, springSnappy, transitionFor } from "./motion";
import { cn } from "./utils";

const collectionItems =
  "[role=option], [role=menuitem], [role=menuitemradio], [role=menuitemcheckbox], [role=row]";

export const itemHighlightRing =
  "focus-visible:outline-1 focus-visible:outline-solid focus-visible:-outline-offset-1 focus-visible:outline-ring in-data-[item-highlight=ring]:focus-visible:outline-none forced-colors:focus-visible:outline-2 forced-colors:focus-visible:outline-solid forced-colors:focus-visible:-outline-offset-2";

const focusVisible =
  ":is([data-rac][data-focus-visible], :not([data-rac]):focus-visible)";

const fade = { duration: duration.fast, ease: easeOut } satisfies Transition;

const snap = { duration: 0 } satisfies Transition;

const curve = createGeneratorEasing(
  { bounce: springSnappy.bounce, duration: springSnappy.duration * 1000 },
  100,
  spring,
);

const glideTiming = {
  duration: curve.duration * 1000,
  easing: generateLinearEasing(curve.ease, curve.duration * 1000),
  fill: "forwards",
} satisfies KeyframeEffectOptions;

type Move = "glide" | "snap";

type Point = { x: number; y: number };

type Box = Point & { width: number; height: number; radius: string };

type Layer =
  | { kind: "hidden" }
  | { kind: "leaving" }
  | { kind: "shown"; target: HTMLElement; box: Box; ring: boolean };

type Flight = { from: Point; to: Point };

type Pointer = Point & {
  over: EventTarget | null;
  item: HTMLElement | null;
};

const translate = ({ x, y }: Point) => `translate(${x}px, ${y}px)`;

const position = (animation: Animation, { from, to }: Flight): Point => {
  const progress = curve.ease(
    Math.min(1, Number(animation.currentTime ?? 0) / glideTiming.duration),
  );
  return {
    x: from.x + (to.x - from.x) * progress,
    y: from.y + (to.y - from.y) * progress,
  };
};

export interface ItemHighlightProps {
  items?: string;
  placement?: "over" | "under";
  ring?: boolean;
  className?: string;
}

export function ItemHighlight({
  items = collectionItems,
  placement = "over",
  ring = false,
  className,
}: ItemHighlightProps) {
  const ref = useRef<HTMLSpanElement>(null);
  const reduceMotion = useReducedMotion();

  useLayoutEffect(() => {
    const layer = ref.current;
    const container = layer?.parentElement;
    if (!layer || !container) return;
    if (
      placement === "under" &&
      container.parentElement?.closest(
        ":has(> [data-slot=item-highlight][data-placement=under])",
      )
    )
      return;
    const rest = placement === "under" ? "under" : "fill";
    const sizeTransition = transitionFor(reduceMotion, springSnappy);
    const focusedItem = `:is(${items})${focusVisible}`;
    const virtualItem = `:is(${items})[data-focused]`;
    let focused: HTMLElement | null = null;
    let last: "pointer" | "focus" = "focus";
    let pointer: Pointer | null = null;
    let state: Layer = { kind: "hidden" };
    let flight: Flight | null = null;
    const glideEffect = new KeyframeEffect(layer, null, glideTiming);
    const glide = new Animation(glideEffect);

    const owned = (node: Element | null): node is HTMLElement =>
      node instanceof HTMLElement &&
      node.closest("[data-item-highlight], [data-empty]") === container &&
      !container.hasAttribute("data-empty");
    const itemAt = (node: Element, previous: HTMLElement | null) => {
      const item = node.closest(items);
      if (!item) return node.querySelector(items) ? previous : null;
      return owned(item) &&
        !item.matches("[data-disabled], [aria-disabled=true]")
        ? item
        : null;
    };
    const live = (item?: HTMLElement | null) =>
      item && container.contains(item) ? item : null;

    const measure = (target: HTMLElement, origin: Element, radius: string) => {
      let x = 0;
      let y = 0;
      for (let node: HTMLElement | null = target; node && node !== origin; ) {
        x += node.offsetLeft;
        y += node.offsetTop;
        node = node.offsetParent as HTMLElement | null;
        if (node && node !== origin) {
          x += node.clientLeft;
          y += node.clientTop;
        }
      }
      return {
        x,
        y,
        width: target.offsetWidth,
        height: target.offsetHeight,
        radius,
      };
    };

    const slide = (to: Point, from: Point | null, move: Move) => {
      if (from && to.x === from.x && to.y === from.y) return;
      const start = from && (flight ? position(glide, flight) : from);
      if (!start || move === "snap" || reduceMotion) {
        glide.cancel();
        flight = null;
        layer.style.transform = translate(to);
        return;
      }
      glideEffect.setKeyframes({
        transform: [translate(start), translate(to)],
      });
      glide.currentTime = 0;
      glide.play();
      flight = { from: start, to };
    };

    const place = (box: Box, from: Box | null, move: Move) => {
      slide(box, from, move);
      if (!from || box.width !== from.width || box.height !== from.height)
        animate(
          layer,
          { width: box.width, height: box.height },
          from && move === "glide" ? sizeTransition : snap,
        );
      if (!from || box.radius !== from.radius)
        animate(layer, { borderRadius: box.radius }, snap);
    };

    const paintRing = (on: boolean) => {
      if (on === (state.kind === "shown" && state.ring)) return;
      layer.toggleAttribute("data-ring", on);
      container.setAttribute("data-item-highlight", on ? "ring" : rest);
    };

    const resize = new ResizeObserver((entries) => {
      const unchanged = entries.every(
        ({ target, borderBoxSize: [size] }) =>
          state.kind === "shown" &&
          target === state.target &&
          Math.round(size.inlineSize) === state.box.width &&
          Math.round(size.blockSize) === state.box.height,
      );
      if (!unchanged) render("glide");
    });

    const hide = () => {
      if (state.kind !== "shown") return;
      paintRing(false);
      resize.unobserve(state.target);
      const leaving: Layer = { kind: "leaving" };
      state = leaving;
      animate(layer, { opacity: 0 }, fade).then(() => {
        if (state !== leaving) return;
        state = { kind: "hidden" };
        animate(layer, { width: 0, height: 0 }, snap);
      });
    };

    const render = (move: Move) => {
      const origin = layer.offsetParent;
      const target =
        origin &&
        (last === "pointer"
          ? (live(pointer?.item) ?? live(focused))
          : (live(focused) ?? live(pointer?.item)));
      if (!target) return hide();
      const kept =
        state.kind === "shown" && state.target === target ? state : null;
      const same = kept !== null;
      const box = measure(
        target,
        origin,
        kept?.box.radius ?? getComputedStyle(target).borderRadius,
      );
      place(
        box,
        state.kind === "shown" ? state.box : null,
        same ? "snap" : move,
      );
      if (state.kind !== "shown") animate(layer, { opacity: 1 }, fade);
      if (!same) {
        if (state.kind === "shown") resize.unobserve(state.target);
        resize.observe(target);
      }
      const onTarget =
        ring && target === focused && target.matches(focusVisible);
      paintRing(onTarget);
      state = { kind: "shown", target, box, ring: onTarget };
    };

    const first = (selector: string) => {
      for (const node of container.querySelectorAll(selector))
        if (owned(node)) return node;
      return null;
    };
    const syncFocus = () => {
      const next =
        first(focusedItem) ??
        (container.contains(document.activeElement)
          ? null
          : first(virtualItem));
      if (next !== focused) {
        focused = next;
        last = "focus";
      }
      render("glide");
    };
    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      if (pointer?.over === event.target && last === "pointer") {
        pointer.x = event.clientX;
        pointer.y = event.clientY;
        return;
      }
      pointer = {
        x: event.clientX,
        y: event.clientY,
        over: event.target,
        item:
          event.target instanceof Element
            ? itemAt(event.target, pointer?.item ?? null)
            : null,
      };
      last = "pointer";
      render("glide");
    };
    const onPointerLeave = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      pointer = null;
      render("glide");
    };
    const onScroll = () => {
      if (!pointer) return;
      const over = document.elementFromPoint(pointer.x, pointer.y);
      if (over === pointer.over) return;
      const item =
        over && container.contains(over) ? itemAt(over, pointer.item) : null;
      const moved = item !== pointer.item;
      pointer = { ...pointer, over, item };
      if (moved) render("snap");
    };

    const mutations = new MutationObserver(syncFocus);
    container.setAttribute("data-item-highlight", rest);
    mutations.observe(container, {
      subtree: true,
      childList: true,
      attributeFilter: ["data-focus-visible", "data-focused"],
    });
    resize.observe(container);
    container.addEventListener("pointermove", onPointerMove);
    container.addEventListener("pointerleave", onPointerLeave);
    container.addEventListener("focusin", syncFocus);
    container.addEventListener("focusout", syncFocus);
    document.addEventListener("scroll", onScroll, {
      capture: true,
      passive: true,
    });
    syncFocus();
    return () => {
      mutations.disconnect();
      resize.disconnect();
      container.removeEventListener("pointermove", onPointerMove);
      container.removeEventListener("pointerleave", onPointerLeave);
      container.removeEventListener("focusin", syncFocus);
      container.removeEventListener("focusout", syncFocus);
      document.removeEventListener("scroll", onScroll, { capture: true });
      container.removeAttribute("data-item-highlight");
      layer.removeAttribute("data-ring");
      glide.cancel();
      animate(layer, { opacity: 0, width: 0, height: 0 }, snap);
    };
  }, [items, placement, ring, reduceMotion]);

  return (
    <span
      ref={ref}
      aria-hidden="true"
      data-slot="item-highlight"
      data-placement={placement}
